"""Tests for the LSP Provider."""
import pytest
from unittest.mock import MagicMock, patch
from pathlib import Path

from src.ast.lsp_provider import LSPProvider, detect_language, EXTENSION_TO_LANGUAGE
from src.ast.models import StructuralAnalysis, CallInfo


class TestLanguageDetection:
    """Test file extension → language mapping."""

    def test_python_detected(self):
        assert detect_language("src/api.py") == "python"
        assert detect_language("types.pyi") == "python"

    def test_typescript_detected(self):
        assert detect_language("app.ts") == "typescript"
        assert detect_language("component.tsx") == "typescript"
        assert detect_language("script.js") == "typescript"
        assert detect_language("component.jsx") == "typescript"

    def test_go_detected(self):
        assert detect_language("main.go") == "go"

    def test_rust_detected(self):
        assert detect_language("lib.rs") == "rust"

    def test_unknown_returns_none(self):
        assert detect_language("README.md") is None
        assert detect_language("Makefile") is None
        assert detect_language("data.csv") is None

    def test_all_extensions_mapped(self):
        """Every extension in EXTENSION_TO_LANGUAGE maps to a valid language."""
        for ext, lang in EXTENSION_TO_LANGUAGE.items():
            assert ext.startswith(".")
            assert isinstance(lang, str)
            assert len(lang) > 0


class TestLSPProviderInit:
    """Test LSPProvider initialization."""

    def test_name_is_lsp(self):
        provider = LSPProvider()
        assert provider.name == "lsp"

    def test_empty_config_no_crash(self):
        provider = LSPProvider(config_path="/nonexistent/path.yaml")
        assert provider._server_configs == {}

    def test_is_available_false_with_no_config(self):
        provider = LSPProvider()
        # No servers configured, but returns True if config is non-empty
        # With empty config, still returns False
        assert not provider.is_available() or provider._server_configs


class TestAnalyzeBatch:
    """Test LSPProvider.analyze_batch()."""

    def test_groups_files_by_language(self):
        provider = LSPProvider()
        provider._server_configs = {"python": {"command": ["pyright"]}}

        # Mock the analyze method to track what gets called
        with patch.object(provider, "_analyze_language_group", return_value={}) as mock:
            provider.analyze_batch([
                "src/api.py",
                "src/models.py",
                "src/app.ts",  # No typescript config
            ])
            # Should group python files together
            mock.assert_called_once()
            args = mock.call_args
            assert args[0][0] == "python"  # language
            assert len(args[0][2]) == 2  # 2 python files

    def test_skips_languages_with_no_config(self):
        provider = LSPProvider()
        provider._server_configs = {}  # No configs

        result = provider.analyze_batch(["src/api.py", "src/app.ts"])
        assert result == {}

    def test_returns_empty_for_empty_input(self):
        provider = LSPProvider()
        assert provider.analyze_batch([]) == {}

    def test_returns_empty_for_non_code_files(self):
        provider = LSPProvider()
        provider._server_configs = {"python": {"command": ["pyright"]}}
        result = provider.analyze_batch(["README.md", "Makefile", "data.csv"])
        assert result == {}


class TestCallInfoMapping:
    """Test LSP response → CallInfo mapping."""

    def test_map_outgoing_call_basic(self):
        provider = LSPProvider()
        call = {
            "to": {
                "name": "execute",
                "uri": "file:///src/db.py",
                "detail": "Database",
            },
            "fromRanges": [{"start": {"line": 38, "character": 8}}],
        }
        result = provider._map_outgoing_call(call, "src/user.py", "UserService.save")
        assert result is not None
        assert result.caller_file == "src/user.py"
        assert result.caller_name == "UserService.save"
        assert result.callee_name == "Database.execute"
        assert result.line == 38

    def test_map_outgoing_call_no_container(self):
        provider = LSPProvider()
        call = {
            "to": {
                "name": "print",
                "uri": "",
            },
            "fromRanges": [{"start": {"line": 10}}],
        }
        result = provider._map_outgoing_call(call, "src/main.py", "main")
        assert result is not None
        assert result.callee_name == "print"
        assert result.callee_file == "-"

    def test_map_outgoing_call_empty_to(self):
        provider = LSPProvider()
        result = provider._map_outgoing_call({}, "src/main.py", "main")
        assert result is None

    def test_map_outgoing_call_no_name(self):
        provider = LSPProvider()
        result = provider._map_outgoing_call(
            {"to": {"uri": "file:///x.py"}}, "src/main.py", "main"
        )
        assert result is None


class TestAutoInstall:
    """Test LSP server auto-installation."""

    def test_auto_install_skips_when_disabled(self):
        provider = LSPProvider()
        provider._auto_install = False
        result = provider._try_auto_install({"auto_install": True, "install_command": "pip install x"})
        assert result is False

    def test_auto_install_skips_when_config_disabled(self):
        provider = LSPProvider()
        result = provider._try_auto_install({"auto_install": False, "install_command": "pip install x"})
        assert result is False

    def test_auto_install_skips_when_no_command(self):
        provider = LSPProvider()
        result = provider._try_auto_install({"auto_install": True, "install_command": None})
        assert result is False

    @patch("shutil.which", return_value=None)
    def test_auto_install_skips_when_pkg_mgr_missing(self, mock_which):
        provider = LSPProvider()
        result = provider._try_auto_install({
            "auto_install": True,
            "install_command": "pip install x",
            "package_manager": "pip",
        })
        assert result is False


class TestSymbolWalking:
    """Test extraction of callable symbols from documentSymbol response."""

    def test_extract_flat_functions(self):
        provider = LSPProvider()
        symbols = [
            {"name": "main", "kind": 12, "range": {"start": {"line": 0, "character": 0}},
             "selectionRange": {"start": {"line": 0, "character": 4}}},
            {"name": "helper", "kind": 12, "range": {"start": {"line": 10, "character": 0}},
             "selectionRange": {"start": {"line": 10, "character": 4}}},
        ]
        result = provider._extract_callable_symbols(symbols)
        assert len(result) == 2
        names = [r[0] for r in result]
        assert "main" in names
        assert "helper" in names

    def test_extract_methods_from_class(self):
        provider = LSPProvider()
        symbols = [
            {
                "name": "UserService", "kind": 5,
                "range": {"start": {"line": 0}},
                "selectionRange": {"start": {"line": 0, "character": 6}},
                "children": [
                    {"name": "get_user", "kind": 6,
                     "range": {"start": {"line": 5}},
                     "selectionRange": {"start": {"line": 5, "character": 8}}},
                    {"name": "save_user", "kind": 6,
                     "range": {"start": {"line": 15}},
                     "selectionRange": {"start": {"line": 15, "character": 8}}},
                ],
            },
        ]
        result = provider._extract_callable_symbols(symbols)
        assert len(result) == 2
        names = [r[0] for r in result]
        assert "UserService.get_user" in names
        assert "UserService.save_user" in names

    def test_skips_non_callable_symbols(self):
        provider = LSPProvider()
        symbols = [
            {"name": "CONSTANT", "kind": 14, "range": {"start": {"line": 0}},
             "selectionRange": {"start": {"line": 0, "character": 0}}},
            {"name": "variable", "kind": 13, "range": {"start": {"line": 1}},
             "selectionRange": {"start": {"line": 1, "character": 0}}},
        ]
        result = provider._extract_callable_symbols(symbols)
        assert len(result) == 0


class TestUriConversion:
    """Test URI to path conversion."""

    def test_file_uri_to_path(self):
        provider = LSPProvider()
        assert provider._uri_to_path("file:///src/api.py") == "src/api.py"

    def test_empty_uri(self):
        provider = LSPProvider()
        assert provider._uri_to_path("") == "-"

    def test_non_file_uri(self):
        provider = LSPProvider()
        assert provider._uri_to_path("https://example.com") == "-"

"""LSP Server Manager — subprocess lifecycle and JSON-RPC communication.

Manages LSP server lifecycle: start → initialize → query → shutdown.
Each server runs as a subprocess communicating via stdio JSON-RPC 2.0
with Content-Length framing.
"""
import json
import logging
import subprocess
import threading
import time
from typing import Optional

logger = logging.getLogger(__name__)


class LSPServerError(Exception):
    """Raised when an LSP server operation fails."""


class LSPTimeoutError(LSPServerError):
    """Raised when an LSP request times out."""


class LSPServerManager:
    """Manages LSP server lifecycle — start, communicate, shutdown.

    Each server runs as a subprocess communicating via stdio JSON-RPC.
    One server per language per analysis run. Not persistent.
    """

    def __init__(self, server_config: dict):
        self.config = server_config
        self._process: Optional[subprocess.Popen] = None
        self._request_id: int = 0
        self._timeout = server_config.get("timeout_per_file", 30)
        self._capabilities: dict = {}
        self._lock = threading.Lock()
        self._notification_buffer: list[dict] = []

    @property
    def capabilities(self) -> dict:
        """Server capabilities from initialize response."""
        return self._capabilities

    def start(self, root_path: str) -> bool:
        """Start the LSP server subprocess.

        Returns True if server started successfully.
        """
        command = self.config.get("command", [])
        if not command:
            logger.error("No command configured for LSP server")
            return False

        try:
            self._process = subprocess.Popen(
                command,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                bufsize=0,
            )
            logger.info(f"LSP server started: {command[0]} (pid={self._process.pid})")
            return True
        except FileNotFoundError:
            logger.error(f"LSP server binary not found: {command[0]}")
            return False
        except Exception as e:
            logger.error(f"Failed to start LSP server: {e}")
            return False

    def initialize(self, root_path: str) -> dict:
        """Send initialize request, return server capabilities."""
        if not self._process:
            raise LSPServerError("Server not started")

        params = {
            "processId": None,
            "rootUri": f"file:///{root_path.replace(chr(92), '/')}",
            "rootPath": root_path,
            "capabilities": {
                "textDocument": {
                    "callHierarchy": {"dynamicRegistration": False},
                    "documentSymbol": {"dynamicRegistration": False},
                },
            },
            "workspaceFolders": [
                {
                    "uri": f"file:///{root_path.replace(chr(92), '/')}",
                    "name": root_path.split("/")[-1] or root_path.split("\\")[-1],
                }
            ],
        }

        result = self.send_request("initialize", params)
        self._capabilities = result.get("capabilities", {})

        # Send initialized notification
        self.send_notification("initialized", {})

        logger.info(f"LSP server initialized (callHierarchy={self.supports_call_hierarchy})")
        return result

    @property
    def supports_call_hierarchy(self) -> bool:
        """Whether the server supports callHierarchy requests."""
        return bool(self._capabilities.get("callHierarchyProvider"))

    def send_request(self, method: str, params: dict) -> dict:
        """Send a JSON-RPC request and wait for response.

        Raises LSPTimeoutError if response not received within timeout.
        """
        if not self._process or self._process.poll() is not None:
            raise LSPServerError("Server not running")

        self._request_id += 1
        request_id = self._request_id

        message = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params,
        }

        self._write_message(message)

        # Read responses until we get the one matching our request ID
        deadline = time.monotonic() + self._timeout
        while time.monotonic() < deadline:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break

            response = self._read_message(timeout=remaining)
            if response is None:
                continue

            # Check if this is a response to our request
            if "id" in response and response["id"] == request_id:
                if "error" in response:
                    error = response["error"]
                    raise LSPServerError(
                        f"LSP error {error.get('code')}: {error.get('message')}"
                    )
                return response.get("result", {})

            # It's a notification or response to another request — buffer it
            if "method" in response and "id" not in response:
                self._notification_buffer.append(response)

        raise LSPTimeoutError(f"Timeout waiting for response to {method} (id={request_id})")

    def send_notification(self, method: str, params: dict):
        """Send a JSON-RPC notification (no response expected)."""
        if not self._process or self._process.poll() is not None:
            raise LSPServerError("Server not running")

        message = {
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        }
        self._write_message(message)

    def shutdown(self):
        """Send shutdown request then exit notification. Kill if unresponsive."""
        if not self._process:
            return

        try:
            if self._process.poll() is None:
                # Try graceful shutdown
                try:
                    self._request_id += 1
                    shutdown_msg = {
                        "jsonrpc": "2.0",
                        "id": self._request_id,
                        "method": "shutdown",
                        "params": None,
                    }
                    self._write_message(shutdown_msg)
                    # Wait briefly for response
                    self._read_message(timeout=3)
                except Exception:
                    pass

                try:
                    exit_msg = {
                        "jsonrpc": "2.0",
                        "method": "exit",
                        "params": None,
                    }
                    self._write_message(exit_msg)
                except Exception:
                    pass

                # Wait for process to exit
                try:
                    self._process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    logger.warning("LSP server did not exit gracefully, killing")
                    self._process.kill()
                    self._process.wait(timeout=2)
        except Exception as e:
            logger.error(f"Error during LSP shutdown: {e}")
            if self._process and self._process.poll() is None:
                self._process.kill()
        finally:
            self._process = None
            logger.info("LSP server stopped")

    def _write_message(self, data: dict):
        """Write a JSON-RPC message with Content-Length framing to stdin."""
        if not self._process or not self._process.stdin:
            raise LSPServerError("Server stdin not available")

        body = json.dumps(data)
        body_bytes = body.encode("utf-8")
        header = f"Content-Length: {len(body_bytes)}\r\n\r\n"

        with self._lock:
            self._process.stdin.write(header.encode("ascii"))
            self._process.stdin.write(body_bytes)
            self._process.stdin.flush()

    def _read_message(self, timeout: float = 30) -> Optional[dict]:
        """Read a JSON-RPC message from server stdout.

        Parses Content-Length header framing. Returns None on timeout or error.
        """
        if not self._process or not self._process.stdout:
            return None

        try:
            # Read headers until we find Content-Length
            content_length = None
            deadline = time.monotonic() + timeout

            while time.monotonic() < deadline:
                if self._process.poll() is not None:
                    return None

                line = self._readline_with_timeout(deadline)
                if line is None:
                    return None

                line_str = line.decode("ascii", errors="replace").strip()
                if line_str == "":
                    # Empty line = end of headers
                    if content_length is not None:
                        break
                    continue

                if line_str.lower().startswith("content-length:"):
                    try:
                        content_length = int(line_str.split(":", 1)[1].strip())
                    except ValueError:
                        continue

            if content_length is None:
                return None

            # Read body
            body_bytes = b""
            while len(body_bytes) < content_length:
                if self._process.poll() is not None:
                    return None
                remaining = content_length - len(body_bytes)
                chunk = self._process.stdout.read(remaining)
                if not chunk:
                    return None
                body_bytes += chunk

            return json.loads(body_bytes.decode("utf-8"))

        except json.JSONDecodeError as e:
            logger.warning(f"JSON parse error reading LSP message: {e}")
            return None
        except Exception as e:
            logger.debug(f"Error reading LSP message: {e}")
            return None

    def _readline_with_timeout(self, deadline: float) -> Optional[bytes]:
        """Read a line from stdout with timeout."""
        if not self._process or not self._process.stdout:
            return None

        # Use a thread to read with timeout
        result = [None]

        def read():
            try:
                result[0] = self._process.stdout.readline()
            except Exception:
                pass

        t = threading.Thread(target=read, daemon=True)
        t.start()
        remaining = max(0.1, deadline - time.monotonic())
        t.join(timeout=remaining)

        if t.is_alive():
            return None
        return result[0]

