def shutdown(self):
    """Send shutdown request then exit notification. Kill if unresponsive."""
    if not self._process:
        return

    try:
        if self._process.poll() is None:
            # Try graceful shutdown
            try:
                self._request_id += 1
                shutdown_msg = {
                    "jsonrpc": "2.0",
                    "id": self._request_id,
                    "method": "shutdown",
                    "params": None,
                }
                self._write_message(shutdown_msg)
                # Wait briefly for response
                self._read_message(timeout=3)
            except Exception:
                pass

            try:
                exit_msg = {
                    "jsonrpc": "2.0",
                    "method": "exit",
                    "params": None,
                }
                self._write_message(exit_msg)
            except Exception:
                pass

            # Wait for process to exit
            try:
                self._process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                logger.warning("LSP server did not exit gracefully, killing")
                self._process.kill()
                self._process.wait(timeout=2)
    except Exception as e:
        logger.error(f"Error during LSP shutdown: {e}")
        if self._process and self._process.poll() is None:
            self._process.kill()
    finally:
        self._process = None
        logger.info("LSP server stopped")

