"""LSP Server Manager — subprocess lifecycle and JSON-RPC communication.

Manages LSP server lifecycle: start → initialize → query → shutdown.
Each server runs as a subprocess communicating via stdio JSON-RPC 2.0
with Content-Length framing.
"""
import json
import logging
import subprocess
import threading
import time
from typing import Optional

logger = logging.getLogger(__name__)


class LSPServerError(Exception):
    """Raised when an LSP server operation fails."""


class LSPTimeoutError(LSPServerError):
    """Raised when an LSP request times out."""


class LSPServerManager:
    """Manages LSP server lifecycle — start, communicate, shutdown.

    Each server runs as a subprocess communicating via stdio JSON-RPC.
    One server per language per analysis run. Not persistent.
    """

    def __init__(self, server_config: dict):
        self.config = server_config
        self._process: Optional[subprocess.Popen] = None
        self._request_id: int = 0
        self._timeout = server_config.get("timeout_per_file", 30)
        self._capabilities: dict = {}
        self._lock = threading.Lock()
        self._notification_buffer: list[dict] = []

    @property
    def capabilities(self) -> dict:
        """Server capabilities from initialize response."""
        return self._capabilities

    def start(self, root_path: str) -> bool:
        """Start the LSP server subprocess.

        Returns True if server started successfully.
        """
        command = self.config.get("command", [])
        if not command:
            logger.error("No command configured for LSP server")
            return False

        try:
            self._process = subprocess.Popen(
                command,
                stdin=subprocess.PIPE,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                bufsize=0,
            )
            logger.info(f"LSP server started: {command[0]} (pid={self._process.pid})")
            return True
        except FileNotFoundError:
            logger.error(f"LSP server binary not found: {command[0]}")
            return False
        except Exception as e:
            logger.error(f"Failed to start LSP server: {e}")
            return False

    def initialize(self, root_path: str) -> dict:
        """Send initialize request, return server capabilities."""
        if not self._process:
            raise LSPServerError("Server not started")

        params = {
            "processId": None,
            "rootUri": f"file:///{root_path.replace(chr(92), '/')}",
            "rootPath": root_path,
            "capabilities": {
                "textDocument": {
                    "callHierarchy": {"dynamicRegistration": False},
                    "documentSymbol": {"dynamicRegistration": False},
                },
            },
            "workspaceFolders": [
                {
                    "uri": f"file:///{root_path.replace(chr(92), '/')}",
                    "name": root_path.split("/")[-1] or root_path.split("\\")[-1],
                }
            ],
        }

        result = self.send_request("initialize", params)
        self._capabilities = result.get("capabilities", {})

        # Send initialized notification
        self.send_notification("initialized", {})

        logger.info(f"LSP server initialized (callHierarchy={self.supports_call_hierarchy})")
        return result

    @property
    def supports_call_hierarchy(self) -> bool:
        """Whether the server supports callHierarchy requests."""
        return bool(self._capabilities.get("callHierarchyProvider"))

    def send_request(self, method: str, params: dict) -> dict:
        """Send a JSON-RPC request and wait for response.

        Raises LSPTimeoutError if response not received within timeout.
        """
        if not self._process or self._process.poll() is not None:
            raise LSPServerError("Server not running")

        self._request_id += 1
        request_id = self._request_id

        message = {
            "jsonrpc": "2.0",
            "id": request_id,
            "method": method,
            "params": params,
        }

        self._write_message(message)

        # Read responses until we get the one matching our request ID
        deadline = time.monotonic() + self._timeout
        while time.monotonic() < deadline:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break

            response = self._read_message(timeout=remaining)
            if response is None:
                continue

            # Check if this is a response to our request
            if "id" in response and response["id"] == request_id:
                if "error" in response:
                    error = response["error"]
                    raise LSPServerError(
                        f"LSP error {error.get('code')}: {error.get('message')}"
                    )
                return response.get("result", {})

            # It's a notification or response to another request — buffer it
            if "method" in response and "id" not in response:
                self._notification_buffer.append(response)

        raise LSPTimeoutError(f"Timeout waiting for response to {method} (id={request_id})")

    def send_notification(self, method: str, params: dict):
        """Send a JSON-RPC notification (no response expected)."""
        if not self._process or self._process.poll() is not None:
            raise LSPServerError("Server not running")

        message = {
            "jsonrpc": "2.0",
            "method": method,
            "params": params,
        }
        self._write_message(message)

    def shutdown(self):
        """Send shutdown request then exit notification. Kill if unresponsive."""
        if not self._process:
            return

        try:
            if self._process.poll() is None:
                # Try graceful shutdown
                try:
                    self._request_id += 1
                    shutdown_msg = {
                        "jsonrpc": "2.0",
                        "id": self._request_id,
                        "method": "shutdown",
                        "params": None,
                    }
                    self._write_message(shutdown_msg)
                    # Wait briefly for response
                    self._read_message(timeout=3)
                except Exception:
                    pass

                try:
                    exit_msg = {
                        "jsonrpc": "2.0",
                        "method": "exit",
                        "params": None,
                    }
                    self._write_message(exit_msg)
                except Exception:
                    pass

                # Wait for process to exit
                try:
                    self._process.wait(timeout=5)
                except subprocess.TimeoutExpired:
                    logger.warning("LSP server did not exit gracefully, killing")
                    self._process.kill()
                    self._process.wait(timeout=2)
        except Exception as e:
            logger.error(f"Error during LSP shutdown: {e}")
            if self._process and self._process.poll() is None:
                self._process.kill()
        finally:
            self._process = None
            logger.info("LSP server stopped")

    def _write_message(self, data: dict):
        """Write a JSON-RPC message with Content-Length framing to stdin."""
        if not self._process or not self._process.stdin:
            raise LSPServerError("Server stdin not available")

        body = json.dumps(data)
        body_bytes = body.encode("utf-8")
        header = f"Content-Length: {len(body_bytes)}\r\n\r\n"

        with self._lock:
            self._process.stdin.write(header.encode("ascii"))
            self._process.stdin.write(body_bytes)
            self._process.stdin.flush()

    def _read_message(self, timeout: float = 30) -> Optional[dict]:
        """Read a JSON-RPC message from server stdout.

        Parses Content-Length header framing. Returns None on timeout or error.
        """
        if not self._process or not self._process.stdout:
            return None

        try:
            # Read headers until we find Content-Length
            content_length = None
            deadline = time.monotonic() + timeout

            while time.monotonic() < deadline:
                if self._process.poll() is not None:
                    return None

                line = self._readline_with_timeout(deadline)
                if line is None:
                    return None

                line_str = line.decode("ascii", errors="replace").strip()
                if line_str == "":
                    # Empty line = end of headers
                    if content_length is not None:
                        break
                    continue

                if line_str.lower().startswith("content-length:"):
                    try:
                        content_length = int(line_str.split(":", 1)[1].strip())
                    except ValueError:
                        continue

            if content_length is None:
                return None

            # Read body
            body_bytes = b""
            while len(body_bytes) < content_length:
                if self._process.poll() is not None:
                    return None
                remaining = content_length - len(body_bytes)
                chunk = self._process.stdout.read(remaining)
                if not chunk:
                    return None
                body_bytes += chunk

            return json.loads(body_bytes.decode("utf-8"))

        except json.JSONDecodeError as e:
            logger.warning(f"JSON parse error reading LSP message: {e}")
            return None
        except Exception as e:
            logger.debug(f"Error reading LSP message: {e}")
            return None

    def _readline_with_timeout(self, deadline: float) -> Optional[bytes]:
        """Read a line from stdout with timeout."""
        if not self._process or not self._process.stdout:
            return None

        # Use a thread to read with timeout
        result = [None]

        def read():
            try:
                result[0] = self._process.stdout.readline()
            except Exception:
                pass

        t = threading.Thread(target=read, daemon=True)
        t.start()
        remaining = max(0.1, deadline - time.monotonic())
        t.join(timeout=remaining)

        if t.is_alive():
            return None
        return result[0]

    def open_file(self, file_path: str, content: str, language_id: str):
        """Send textDocument/didOpen notification."""
        uri = f"file:///{file_path.replace(chr(92), '/')}"
        self.send_notification("textDocument/didOpen", {
            "textDocument": {
                "uri": uri,
                "languageId": language_id,
                "version": 1,
                "text": content,
            }
        })

    def close_file(self, file_path: str):
        """Send textDocument/didClose notification."""
        uri = f"file:///{file_path.replace(chr(92), '/')}"
        self.send_notification("textDocument/didClose", {
            "textDocument": {"uri": uri}
        })

    def get_document_symbols(self, file_path: str) -> list:
        """Request textDocument/documentSymbol."""
        uri = f"file:///{file_path.replace(chr(92), '/')}"
        result = self.send_request("textDocument/documentSymbol", {
            "textDocument": {"uri": uri}
        })
        return result if isinstance(result, list) else []

    def get_call_hierarchy_items(self, file_path: str, line: int, character: int) -> list:
        """Request callHierarchy/prepareCallHierarchy."""
        uri = f"file:///{file_path.replace(chr(92), '/')}"
        result = self.send_request("callHierarchy/prepareCallHierarchy", {
            "textDocument": {"uri": uri},
            "position": {"line": line, "character": character},
        })
        return result if isinstance(result, list) else []

    def get_outgoing_calls(self, item: dict) -> list:
        """Request callHierarchy/outgoingCalls."""
        result = self.send_request("callHierarchy/outgoingCalls", {
            "item": item,
        })
        return result if isinstance(result, list) else []

