    manager = LSPServerManager({
        **config,
        "timeout_per_file": config.get("timeout_per_file", 30),
    })

    try:
        if not manager.start(project_root):
            return {}

        init_result = manager.initialize(project_root)
        supports_calls = manager.supports_call_hierarchy

        results: dict[str, StructuralAnalysis] = {}

        for file_path in file_paths:
            try:
                analysis = self._analyze_single_file(
                    manager, file_path, language, supports_calls
                )
                if analysis:
                    results[file_path] = analysis
            except LSPTimeoutError:
                logger.warning(f"LSP timeout for {file_path}, skipping")
            except LSPServerError as e:
                logger.warning(f"LSP error for {file_path}: {e}")
            except Exception as e:
                logger.error(f"Unexpected error analyzing {file_path}: {e}")

        return results

    except Exception as e:
        logger.error(f"LSP server failed for {language}: {e}")
        return {}
    finally:
        manager.shutdown()

def _analyze_single_file(
    self, manager: LSPServerManager, file_path: str,
    language: str, supports_calls: bool
) -> Optional[StructuralAnalysis]:
    """Analyze a single file via LSP, extracting call graph."""
    try:
        content = Path(file_path).read_text(encoding="utf-8")
    except Exception:
        return None

    language_id = self._get_language_id(language)
    manager.open_file(file_path, content, language_id)

    calls: list[CallInfo] = []

    try:
        if supports_calls:
            # Get document symbols to find functions/methods
            symbols = manager.get_document_symbols(file_path)
            callable_symbols = self._extract_callable_symbols(symbols)

            for sym_name, sym_kind, line, character in callable_symbols:
                try:
                    items = manager.get_call_hierarchy_items(
                        file_path, line, character
                    )
                    if not items:
                        continue

                    for item in items:
                        outgoing = manager.get_outgoing_calls(item)
                        for call in outgoing:
                            call_info = self._map_outgoing_call(
                                call, file_path, sym_name
                            )
                            if call_info:
                                calls.append(call_info)
                except (LSPTimeoutError, LSPServerError):
                    continue

        return StructuralAnalysis(
            file_path=file_path,
            language=language,
            calls=calls,
            provider_used="lsp",
            analysis_depth="rich",
        )
    finally:
        try:
            manager.close_file(file_path)
        except Exception:
            pass

def _extract_callable_symbols(self, symbols: list) -> list[tuple]:
    """Extract function/method symbols from documentSymbol response.

    Returns list of (qualified_name, kind, line, character) tuples.
    """
    result = []
    self._walk_symbols(symbols, None, result)
    return result

def _walk_symbols(self, symbols: list, parent_name: Optional[str], result: list):
    """Recursively walk symbol tree extracting callable symbols."""
    for sym in symbols:
        kind = sym.get("kind", 0)
        name = sym.get("name", "")
        range_info = sym.get("selectionRange") or sym.get("range", {})
        start = range_info.get("start", {})
        line = start.get("line", 0)
        character = start.get("character", 0)

        qualified_name = f"{parent_name}.{name}" if parent_name else name

        # Functions (12), Methods (6), Constructors (9)
        if kind in (6, 9, 12):
            result.append((qualified_name, kind, line, character))

        # Recurse into children (class methods, etc.)
        children = sym.get("children", [])
        if children:
            # For classes, use class name as parent
            child_parent = name if kind == 5 else parent_name
            self._walk_symbols(children, child_parent, result)

def _map_outgoing_call(
    self, call: dict, caller_file: str, caller_name: str
) -> Optional[CallInfo]:
    """Map an LSP outgoing call to our CallInfo model."""
    to = call.get("to") or call.get("callee")
    if not to:
        return None

    callee_name = to.get("name", "")
    if not callee_name:
        return None

    # Extract callee file from URI
    callee_uri = to.get("uri", "")
    callee_file = self._uri_to_path(callee_uri) if callee_uri else "-"

    # Get call site line
    from_ranges = call.get("fromRanges", [])
    line = 0
    if from_ranges:
        line = from_ranges[0].get("start", {}).get("line", 0)

    # Build qualified callee name
    # If callee has a containerName, use it
    container = to.get("detail", "") or to.get("containerName", "")
    if container:
        callee_qualified = f"{container}.{callee_name}"
    else:
        callee_qualified = callee_name

    return CallInfo(
        caller_file=caller_file,
        caller_name=caller_name,
        callee_file=callee_file,
        callee_name=callee_qualified,
        line=line,
    )

