        return calls

    def extract_assignments(self, source: bytes) -> dict[str, str]:
        """Extract self.x = ClassName() assignments from class bodies."""
        tree = self._parser.parse(source)
        assignments = {}
        self._walk_assignments(tree.root_node, None, assignments)
        return assignments

    def extract_annotations(self, source: bytes) -> dict[str, str]:
        """Extract type annotations from class bodies and function params."""
        tree = self._parser.parse(source)
        annotations = {}
        self._walk_annotations(tree.root_node, None, annotations)
        return annotations

    def _walk(self, node: Node, file_path: str, calls: list[RawCallSite]):
        """Recursively walk AST to find call expressions."""
        if node.type == "call":
            call_site = self._extract_call(node, file_path)
            if call_site:
                calls.append(call_site)

        for child in node.children:
            self._walk(child, file_path, calls)

    def _extract_call(self, node: Node, file_path: str) -> Optional[RawCallSite]:
        """Extract a RawCallSite from a call node."""
        func = node.child_by_field_name("function")
        if not func:
            return None

        caller_name = self._find_enclosing_function(node)
        line = node.start_point[0] + 1  # 1-indexed

        if func.type == "attribute":
            obj = func.child_by_field_name("object")
            attr = func.child_by_field_name("attribute")
            if obj and attr:
                return RawCallSite(
                    file_path=file_path,
                    caller_name=caller_name,
                    receiver=obj.text.decode("utf-8"),
                    method=attr.text.decode("utf-8"),
                    line=line,
                )
        elif func.type == "identifier":
            name = func.text.decode("utf-8")
            return RawCallSite(
                file_path=file_path,
                caller_name=caller_name,
                receiver=None,
                method=name,
                line=line,
            )

        return None

    def _find_enclosing_function(self, node: Node) -> str:
        """Walk up AST to find enclosing function/method name."""
        current = node.parent
        func_name = None
        class_name = None

        while current:
            if current.type == "function_definition" and func_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    func_name = name_node.text.decode("utf-8")

            if current.type == "class_definition" and class_name is None:
                name_node = current.child_by_field_name("name")
                if name_node:
                    class_name = name_node.text.decode("utf-8")

            current = current.parent

        if class_name and func_name:
            return f"{class_name}.{func_name}"
        elif func_name:
            return func_name
        return "<module>"

    def _walk_assignments(self, node: Node, class_name: Optional[str], result: dict):
        """Find self.x = ClassName() patterns."""
        if node.type == "class_definition":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_assignments(child, cn, result)
            return

        if node.type == "assignment" and class_name:
            left = node.children[0] if node.children else None
            right = node.children[-1] if len(node.children) >= 3 else None

            if left and right and left.type == "attribute":
                obj = left.child_by_field_name("object")
                attr = left.child_by_field_name("attribute")
                if obj and attr and obj.text == b"self":
                    attr_name = attr.text.decode("utf-8")
                    # Check if RHS is a constructor call: ClassName()
                    resolved = self._resolve_rhs_class(right)
                    if resolved:
                        result[f"{class_name}.{attr_name}"] = resolved

        for child in node.children:
            self._walk_assignments(child, class_name, result)

    def _resolve_rhs_class(self, node: Node) -> Optional[str]:
        """If node is ClassName(), return ClassName."""
        if node.type == "call":
            func = node.child_by_field_name("function")
            if func and func.type == "identifier":
                name = func.text.decode("utf-8")
                # Heuristic: PascalCase = class constructor
                if name[0].isupper():
                    return name
        return None

    def _walk_annotations(self, node: Node, class_name: Optional[str], result: dict):
        """Find type annotations on class attrs and function params."""
        if node.type == "class_definition":
            name_node = node.child_by_field_name("name")
            cn = name_node.text.decode("utf-8") if name_node else None
            for child in node.children:
                self._walk_annotations(child, cn, result)
            return

        # Class-level annotation: attr: Type
        if node.type == "type_alias_statement" or (
            node.type == "expression_statement" and class_name
        ):
            # Check for annotated assignment or standalone annotation
            pass

        # Typed parameter in function def
        if node.type == "function_definition" and class_name:
            params = node.child_by_field_name("parameters")
            if params:
                for param in params.named_children:
                    if param.type == "typed_parameter":
                        name_node = param.children[0] if param.children else None
                        type_node = param.child_by_field_name("type")
                        if name_node and type_node:
                            param_name = name_node.text.decode("utf-8")
                            type_name = type_node.text.decode("utf-8")
                            if param_name != "self" and type_name[0].isupper():
                                result[f"{class_name}.{param_name}"] = type_name

        # Annotated assignment: self.x: Type = ...
        if node.type == "assignment" and class_name:
            # Check for type annotation on assignment
            left = node.children[0] if node.children else None
            if left and left.type == "type":
                pass  # handled by typed_assignment

        for child in node.children:
            self._walk_annotations(child, class_name, result)


class CallResolver:
    """Multi-stage pipeline for resolving call targets."""

    def resolve(self, call: RawCallSite, context: ResolutionContext) -> CallInfo:
        """Resolve a raw call site to a CallInfo with confidence."""
        # Stage 1: Assignment tracker
        result = self._resolve_via_assignment(call, context)
        if result:
            return result

        # Stage 2: Type annotations
        result = self._resolve_via_annotation(call, context)
        if result:
            return result

        # Stage 3: Import following
        result = self._resolve_via_import(call, context)
        if result:
            return result

        # Stage 4: Ctags cross-reference
        result = self._resolve_via_ctags(call, context)
        if result:
            return result

        # Stage 5: Convention heuristic
        result = self._resolve_via_convention(call, context)
        if result:
            return result

        # Unresolved — emit with low confidence
        callee_name = f"{call.receiver}.{call.method}" if call.receiver else call.method
        return CallInfo(
            caller_file=call.file_path,
            caller_name=call.caller_name,
            callee_file="-",
            callee_name=callee_name,
            line=call.line,
            confidence=0.20,
        )

    def _resolve_via_assignment(
        self, call: RawCallSite, ctx: ResolutionContext
    ) -> Optional[CallInfo]:
        """Resolve via self.x = ClassName() tracking."""
        if not call.receiver:
            return None

        # Extract class context from caller: "UserService.get_user" → "UserService"
        caller_class = call.caller_name.split(".")[0] if "." in call.caller_name else None
        if not caller_class:
            return None

        # Check if receiver matches a tracked assignment
        # self.db → look up "UserService.db"
        receiver_parts = call.receiver.split(".")
        if len(receiver_parts) == 2 and receiver_parts[0] == "self":
            attr_name = receiver_parts[1]
            key = f"{caller_class}.{attr_name}"
            resolved_type = ctx.assignments.get(key)
            if resolved_type:
                callee_name = f"{resolved_type}.{call.method}"
                callee_file = ctx.class_index.get(resolved_type, "-")
                return CallInfo(
                    caller_file=call.file_path,
                    caller_name=call.caller_name,
                    callee_file=callee_file,
                    callee_name=callee_name,
                    line=call.line,
                    confidence=0.95,
                )

        return None

    def _resolve_via_annotation(
        self, call: RawCallSite, ctx: ResolutionContext
    ) -> Optional[CallInfo]:
        """Resolve via type annotations."""
        if not call.receiver:
            return None

        caller_class = call.caller_name.split(".")[0] if "." in call.caller_name else None
        if not caller_class:
            return None

        receiver_parts = call.receiver.split(".")
        if len(receiver_parts) == 2 and receiver_parts[0] == "self":
            attr_name = receiver_parts[1]
            key = f"{caller_class}.{attr_name}"
            resolved_type = ctx.annotations.get(key)
            if resolved_type:
                callee_name = f"{resolved_type}.{call.method}"
                callee_file = ctx.class_index.get(resolved_type, "-")
                return CallInfo(
                    caller_file=call.file_path,
                    caller_name=call.caller_name,
                    callee_file=callee_file,
                    callee_name=callee_name,
                    line=call.line,
                    confidence=0.90,
                )

        return None

    def _resolve_via_import(
        self, call: RawCallSite, ctx: ResolutionContext
    ) -> Optional[CallInfo]:
        """Resolve bare function/class calls via import data."""
        if call.receiver:
            return None  # Import resolution is for bare calls

        import_info = ctx.imports.get(call.method)
        if import_info:
            module_path, original_name = import_info
            # Check if it's a class constructor
            callee_file = ctx.class_index.get(call.method, module_path)
            callee_name = call.method
            is_external = not module_path.startswith("src")
            return CallInfo(
                caller_file=call.file_path,
                caller_name=call.caller_name,
                callee_file="-" if is_external else callee_file,
                callee_name=callee_name,
                line=call.line,
                confidence=0.85,
            )

        return None

    def _resolve_via_ctags(
        self, call: RawCallSite, ctx: ResolutionContext
    ) -> Optional[CallInfo]:
        """Resolve via ctags symbol index — search for method name."""
        matches = ctx.symbol_index.get(call.method, [])
        if not matches:
            return None

        caller_dir = str(Path(call.file_path).parent)

        if len(matches) == 1:
            class_name, file_path = matches[0]
            callee_name = f"{class_name}.{call.method}" if class_name else call.method
            confidence = 0.70
            # Same directory bonus
            if str(Path(file_path).parent) == caller_dir:
                confidence = min(0.95, confidence + 0.10)
            return CallInfo(
                caller_file=call.file_path,
                caller_name=call.caller_name,
                callee_file=file_path,
                callee_name=callee_name,
                line=call.line,
                confidence=confidence,
            )

        # Ambiguous — return best match (same directory preferred)
        for class_name, file_path in matches:
            if str(Path(file_path).parent) == caller_dir:
                callee_name = f"{class_name}.{call.method}" if class_name else call.method
                return CallInfo(
                    caller_file=call.file_path,
                    caller_name=call.caller_name,
                    callee_file=file_path,
                    callee_name=callee_name,
                    line=call.line,
                    confidence=0.50,
                )

        # No directory match, pick first
        class_name, file_path = matches[0]
        callee_name = f"{class_name}.{call.method}" if class_name else call.method
        return CallInfo(
            caller_file=call.file_path,
            caller_name=call.caller_name,
            callee_file=file_path,
            callee_name=callee_name,
            line=call.line,
            confidence=0.40,
        )

    def _resolve_via_convention(
        self, call: RawCallSite, ctx: ResolutionContext
    ) -> Optional[CallInfo]:
        """Last resort: name similarity heuristic."""
        if not call.receiver:
            return None

        # Extract the base receiver name: self.db → db, x → x
        receiver_parts = call.receiver.split(".")
        base_name = receiver_parts[-1]

        # snake_case → PascalCase match against known classes
        pascal = _snake_to_pascal(base_name)
        if pascal in ctx.class_index:
            callee_name = f"{pascal}.{call.method}"
            return CallInfo(
                caller_file=call.file_path,
                caller_name=call.caller_name,
                callee_file=ctx.class_index[pascal],
                callee_name=callee_name,
                line=call.line,
                confidence=0.30,
            )

        return None


class TreeSitterProvider(AnalysisProvider):
    """Call graph extraction via tree-sitter AST parsing."""

    def __init__(self, index_path: Optional[str] = None, imports_path: Optional[str] = None):
        self._index_path = index_path
        self._imports_path = imports_path
        self._extractor = CallExtractor()
        self._resolver = CallResolver()

    @property
    def name(self) -> str:
        return "treesitter"

    def is_available(self) -> bool:
        try:
            import tree_sitter_python
            return True
        except ImportError:
            return False

    def analyze_batch(self, file_paths: list[str]) -> dict[str, StructuralAnalysis]:
        """Parse all files, extract calls, resolve targets."""
        # Filter to Python files only (Phase 1)
        py_files = [f for f in file_paths if f.endswith((".py", ".pyi"))]
        if not py_files:
            return {}

        # Phase 1: Parse all files, extract raw call sites + assignments + annotations
        all_calls: dict[str, list[RawCallSite]] = {}
        all_assignments: dict[str, str] = {}
        all_annotations: dict[str, str] = {}

        for fp in py_files:
            try:
                source = Path(fp).read_bytes()
            except Exception:
                continue

            calls = self._extractor.extract(source, fp)
            if calls:
                all_calls[fp] = calls

            assignments = self._extractor.extract_assignments(source)
            all_assignments.update(assignments)

            annotations = self._extractor.extract_annotations(source)
            all_annotations.update(annotations)

        # Phase 2: Build resolution context
        context = ResolutionContext(
            assignments=all_assignments,
            annotations=all_annotations,
        )

        # Load ctags index if available
        if self._index_path:
            context.symbol_index, context.class_index = _parse_index(self._index_path)

        # Load imports if available
        if self._imports_path:
            context.imports = _parse_imports(self._imports_path)

        # Phase 3: Resolve each call
        results: dict[str, StructuralAnalysis] = {}
        for fp in py_files:
            raw = all_calls.get(fp, [])
            resolved = [self._resolver.resolve(c, context) for c in raw]

            results[fp] = StructuralAnalysis(
                file_path=fp,
                language="python",
                calls=resolved,
                provider_used="treesitter",
                analysis_depth="rich",
            )

        total_calls = sum(len(a.calls) for a in results.values())
        if total_calls:
            logger.info(f"Tree-sitter: {len(results)} files, {total_calls} call edges")

        return results


def _snake_to_pascal(name: str) -> str:
    """Convert snake_case to PascalCase."""
    return "".join(word.capitalize() for word in name.split("_"))


def _parse_index(index_path: str) -> tuple[dict[str, list[tuple[str, str]]], dict[str, str]]:
    """Parse _index.txt into symbol_index and class_index."""
    symbol_index: dict[str, list[tuple[str, str]]] = {}
    class_index: dict[str, str] = {}

    try:
        with open(index_path) as f:
            for line in f:
                if line.startswith("#") or not line.strip():
                    continue
                parts = line.strip().split("\t")
                if len(parts) < 4:
                    continue
                file_path, kind, name, scope = parts[0], parts[1], parts[2], parts[3]

                if kind == "class":
                    class_index[name] = file_path

                if kind in ("method", "function"):
                    class_name = scope if scope != "-" else ""
                    symbol_index.setdefault(name, []).append((class_name, file_path))
    except FileNotFoundError:
        pass

    return symbol_index, class_index


def _parse_imports(imports_path: str) -> dict[str, tuple[str, str]]:
    """Parse _imports.txt into {name: (module_path, name)} dict."""
    imports: dict[str, tuple[str, str]] = {}

    try:
        with open(imports_path) as f:
            for line in f:
                if line.startswith("#") or not line.strip():
                    continue
                parts = line.strip().split("\t")
                if len(parts) < 3:
                    continue
                file_path, module, names = parts[0], parts[1], parts[2]
                for name in names.split(","):
                    name = name.strip()
                    if name:
                        imports[name] = (module.replace(".", "/") + ".py", name)
    except FileNotFoundError:
        pass

    return imports

